import numpy as np

# 用一个简化的词向量矩阵示意
vocab = {"apple": 0, "banana": 1, "cat": 2, "dog": 3, "data": 4}
E = np.array([
    [0.9, 0.1, 0.0],   # apple
    [0.8, 0.2, 0.1],   # banana
    [0.1, 0.9, 0.0],   # cat
    [0.2, 0.8, 0.1],   # dog
    [0.1, 0.1, 0.9],   # data
])

def embed(word):
    return E[vocab[word]]

def cosine(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

print("cat 与 dog 相似度:", round(cosine(embed("cat"), embed("dog")), 3))
print("cat 与 data 相似度:", round(cosine(embed("cat"), embed("data")), 3))

